package android.graphics.drawable; import android.graphics.*; import android.content.res.*; public class BitmapDrawable extends Drawable { private Bitmap bitmap; private Paint paint=new Paint(); public BitmapDrawable(){} public BitmapDrawable(Bitmap b){bitmap=b;} public BitmapDrawable(Resources r,Bitmap b){bitmap=b;} public void setTileModeX(Shader.TileMode m){} public void setTileModeY(Shader.TileMode m){} public Bitmap getBitmap(){return bitmap;} public Paint getPaint(){return paint;} public int getIntrinsicWidth(){return bitmap==null?-1:bitmap.getWidth();} public int getIntrinsicHeight(){return bitmap==null?-1:bitmap.getHeight();} public void draw(Canvas c){if(bitmap!=null){paint.setAlpha(getAlpha());c.drawBitmap(bitmap,null,getBounds(),paint);}else super.draw(c);} }